let generatedSlice=null;
const generateMode=document.querySelector('[data-mode="image"]');generateMode.innerHTML='<strong>✦ 描述生成 Slice</strong><span>写下想法，或上传你的图片</span>';
const genPanel=document.createElement('section');genPanel.id='generation-panel';genPanel.innerHTML=`<label>你想做一个什么样的 Slice？<textarea id="slice-prompt" rows="4" maxlength="800" placeholder="例如：做一个周末去哪玩的选择卡，选项是公园、书店、咖啡馆。也可以上传照片，做成点击揭晓的小故事。"></textarea></label><div class="prompt-examples"><button type="button" data-prompt-example="做一个周末去哪玩的选择卡。选项：公园、书店、咖啡馆">周末选择</button><button type="button" data-prompt-example="做一个下班放松清单。步骤：放下手机、出去散步、听一首歌">生活清单</button><button type="button" data-prompt-example="做一个点击揭晓的照片故事。答案：普通的一天，也值得被好好记住。">照片故事</button></div><label>互动方式<select id="generation-kind"><option value="auto">根据描述选择</option><option value="poll">选择卡</option><option value="checklist">步骤清单</option><option value="reveal">点击揭晓</option></select></label><button type="button" id="generate-slice" class="dark">✦ 生成 Slice</button><p class="generation-note">原型生成：按关键词套用可交互模板，尚未接入 AI；不会识别图片内容。生成后可修改描述并重新生成。</p><p id="generation-status" role="status"></p>`;
uploadFields.prepend(genPanel);document.querySelector('#image-options').hidden=true;
const genModeBefore=setCreationMode;setCreationMode=function(mode,clear=true){if(clear)generatedSlice=null;genModeBefore(mode,clear);genPanel.hidden=mode!=='image';document.querySelector('#image-options').hidden=true;drop.querySelector('strong').textContent=mode==='image'?'上传图片（可选），也可以只写描述':'拖放文件，或点击选择';if(mode==='image')document.querySelector('#upload-hint').textContent='PNG / JPG / WEBP · 最大 2 MB · 作为 Slice 配图'};
function promptConfig(prompt,kind){const actual=kind==='auto'?(/清单|步骤|打卡|待办/.test(prompt)?'checklist':/选项|选择|投票|去哪/.test(prompt)?'poll':'reveal'):kind;let items=(prompt.match(/(?:选项|步骤|清单)[:：]([^。\n]+)/)||[])[1];items=(items||'').split(/[、,，;；\n]/).map(s=>s.trim()).filter(Boolean).slice(0,6);if(items.length<2)items=actual==='checklist'?['开始尝试','记录发现','完成分享']:['想试试','再想想'];const answer=(prompt.match(/(?:答案|揭晓|故事)[:：]([\s\S]+)/)||[])[1]||prompt;return {kind:actual,items,answer,title:prompt.split(/[。\n]/)[0].slice(0,45)||'我的图片故事'}}
function makeGeneratedHtml(config,prompt,asset){const img=/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(asset)?`<img src="${asset}" alt="上传的配图">`:'';const content=config.kind==='checklist'?config.items.map(x=>`<label><input type="checkbox" onchange="document.querySelector('#result').textContent=document.querySelectorAll('input:checked').length+' / ${config.items.length} 已完成'">${escapeHtml(x)}</label>`).join(''):config.kind==='poll'?config.items.map(x=>`<button onclick="document.querySelectorAll('button').forEach(b=>b.classList.remove('selected'));this.classList.add('selected');document.querySelector('#result').textContent='你选择了：'+this.textContent">${escapeHtml(x)}</button>`).join(''):`<button onclick="let a=document.querySelector('#answer');a.hidden=!a.hidden;this.textContent=a.hidden?'点击揭晓':'收起';">点击揭晓</button><p id="answer" hidden>${escapeHtml(config.answer)}</p>`;return `<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><style>*{box-sizing:border-box}body{margin:0;background:#edf4df;color:#273321;font:15px system-ui;line-height:1.7}img{width:100%;max-height:170px;object-fit:cover}.body{padding:22px}small{font-size:10px;letter-spacing:2px;color:#778365}h2{font-size:23px;line-height:1.4;margin:12px 0 18px}button{font:inherit;border:1px solid #cdd6be;background:white;padding:9px 14px;margin:4px;border-radius:20px;cursor:pointer}.selected{background:#c9f277}label{display:flex;gap:10px;padding:9px;background:#ffffff80;margin:5px 0;border-radius:7px}input{accent-color:#667c42}#result{font-size:12px;color:#697c53}#answer{background:white;padding:14px;border-radius:8px;white-space:pre-wrap}</style><body>${img}<div class="body"><small>YOUR LITTLE SLICE</small><h2>${escapeHtml(config.title)}</h2>${content}<p id="result" role="status"></p></div></body></html>`}
const genFormBefore=formData;formData=function(){const d=genFormBefore();if(creationMode!=='image')return d;return {...d,generationPrompt:document.querySelector('#slice-prompt').value.trim(),generationKind:document.querySelector('#generation-kind').value,generationImage:fileAsset,generationFileName:fileName,generationSource:generatedSlice?.html||'',assetType:generatedSlice?'html':'image',asset:generatedSlice?.html||fileAsset}};
const genPreviewBefore=updatePublishPreview;updatePublishPreview=function(reset=false){if(creationMode!=='image')return genPreviewBefore(reset);const d=formData();document.querySelector('#preview-title').textContent=d.title||'你的下一篇 Slice';document.querySelector('#preview-desc').textContent=d.desc||'写下描述，生成后在这里直接试玩。';document.querySelector('#preview-author').textContent=d.author;document.querySelector('#publish-slice').innerHTML=generatedSlice?importedStage({...d,assetType:'html',asset:generatedSlice.html}):'<div class="upload-empty"><span>✦</span><strong>从一句话开始</strong><p>可附上图片、Word、TXT 或 PDF，生成后即可试玩。</p></div>'};
document.querySelectorAll('[data-prompt-example]').forEach(b=>b.onclick=()=>{document.querySelector('#slice-prompt').value=b.dataset.promptExample;document.querySelector('#generation-status').textContent='已填入示例，点击生成即可试玩。'});
document.querySelector('#generate-slice').onclick=()=>{const prompt=document.querySelector('#slice-prompt').value.trim(),kind=document.querySelector('#generation-kind').value;if(readingFile){document.querySelector('#generation-status').textContent='请等待图片读取完成。';return}if(!prompt&&!fileAsset){document.querySelector('#generation-status').textContent='请写下描述，或上传一张图片。';return}const description=prompt||'做一个点击揭晓的照片故事。答案：点击照片，留住这一刻。';const config=promptConfig(description,kind);generatedSlice={html:makeGeneratedHtml(config,description,fileAsset),prompt,kind,image:fileAsset};publishForm.elements.title.value=config.title;publishForm.elements.description.value=(prompt||'我想分享的一个生活瞬间。').slice(0,160);publishForm.elements.category.value='Fun & Social';document.querySelector('#generation-status').textContent='已生成'+({poll:'选择卡',checklist:'步骤清单',reveal:'点击揭晓'}[config.kind])+'，可以直接试玩或修改描述再生成。';document.querySelector('#publish-error').textContent='';updatePublishPreview(true)};
const genCreatorBefore=openCreator;openCreator=function(work){genCreatorBefore(work);const d=work||readStored(draftKey,null);if(d&&typeof d.generationSource==='string'&&d.generationSource){fileAsset=d.generationImage||'';fileName=d.generationFileName||'';document.querySelector('#slice-prompt').value=d.generationPrompt||'';document.querySelector('#generation-kind').value=d.generationKind||'auto';generatedSlice={html:d.generationSource,prompt:d.generationPrompt||'',kind:d.generationKind||'auto',image:fileAsset};setCreationMode('image',false)}else{genPanel.hidden=creationMode!=='image';document.querySelector('#image-options').hidden=true}};
const genSubmitBefore=publishForm.onsubmit;publishForm.onsubmit=e=>{if(creationMode==='image'){if(!generatedSlice){e.preventDefault();document.querySelector('#publish-error').textContent='请先生成 Slice，再试玩并发布。';return}if(generatedSlice.prompt!==document.querySelector('#slice-prompt').value.trim()||generatedSlice.kind!==document.querySelector('#generation-kind').value||generatedSlice.image!==fileAsset){e.preventDefault();document.querySelector('#publish-error').textContent='描述、图片或互动方式已变更，请重新生成后发布。';return}}genSubmitBefore(e)};
genPanel.hidden=creationMode!=='image';if(creationMode==='image')setCreationMode('image',false);
